import { fieldVariants, type FieldVariants } from "./variants.ts";
import { cn } from "../../../lib/utils.ts";

export interface Input extends Marko.Input<"div">, FieldVariants {
  /**
   * Marks the field as invalid. Sets `data-invalid` on the wrapper, which every
   * descendant part restyles against via `group-data-*` selectors. The matching
   * `aria-invalid` belongs on the control itself.
   */
  invalid?: boolean;
  /** Sets `data-disabled`, dimming the label and title. */
  disabled?: boolean;
}

<const/{
  orientation = "vertical",
  invalid,
  disabled,
  class: className,
  content,
  ...rest
}=input/>

<div
  role="group"
  data-slot="field"
  data-orientation=orientation
  data-invalid=(invalid ? "true" : undefined)
  data-disabled=(disabled ? "true" : undefined)
  class=cn(fieldVariants({ orientation }), className)
  ...rest
>
  <${content}/>
</div>

import { cva, type VariantProps } from "class-variance-authority";

export const fieldVariants = cva("data-[invalid=true]:text-destructive gap-3 group/field flex w-full", {
  variants: {
    orientation: {
      vertical: "flex-col *:w-full [&>.sr-only]:w-auto",
      horizontal:
        "flex-row items-center has-[>[data-slot=field-content]]:items-start *:data-[slot=field-label]:flex-auto has-[>[data-slot=field-content]]:[&>[role=checkbox],[role=radio]]:mt-px",
      responsive:
        "flex-col *:w-full @md/field-group:flex-row @md/field-group:items-center @md/field-group:*:w-auto @md/field-group:has-[>[data-slot=field-content]]:items-start @md/field-group:*:data-[slot=field-label]:flex-auto [&>.sr-only]:w-auto @md/field-group:has-[>[data-slot=field-content]]:[&>[role=checkbox],[role=radio]]:mt-px",
    },
  },
  defaultVariants: {
    orientation: "vertical",
  },
});

export type FieldVariants = VariantProps<typeof fieldVariants>;

/**
 * An error as accepted by `<field-error>`: a plain message, or any object with a
 * `message` — which is the shape of a Standard Schema issue, so validators such as
 * valibot, zod and arktype can be passed through unchanged.
 */
export type FieldErrorLike = string | { message?: string } | null | undefined;

/**
 * Normalizes the many accepted error shapes into a de-duplicated list of messages,
 * preserving first-seen order. Mirrors the de-duplication in shadcn's `FieldError`.
 */
export function normalizeFieldErrors(
  errors: FieldErrorLike | readonly FieldErrorLike[],
): string[] {
  const list = Array.isArray(errors) ? errors : [errors];
  const messages: string[] = [];

  for (const error of list as readonly FieldErrorLike[]) {
    const message = typeof error === "string" ? error : error?.message;
    if (message && !messages.includes(message)) {
      messages.push(message);
    }
  }

  return messages;
}
